import json
from pathlib import Path

root=Path(__file__).resolve().parents[2]/'docs/source-plan/v2'
data={name:json.loads((root/file).read_text()) for name,file in {'actions':'ui-actions.json','fields':'ui-fields.json','nodes':'node-catalog.json','plan':'implementation-plan.json','findings':'findings.json','events':'ui-delegates.json','ux':'compact-ux.json'}.items()}
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoReels Studio · Source Plan V2.1</title><style>
[hidden]{display:none!important}:root{font:14px/1.5 system-ui,Segoe UI,sans-serif;color:#202c40;background:#f3f5f9}*{box-sizing:border-box}body{margin:0}header{background:white;border-bottom:1px solid #e3e8f0;padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:16px}h1{font-size:22px;margin:0}h2{font-size:18px;margin:0 0 12px}p{margin:5px 0;color:#66758b}.badge{font-size:12px;padding:5px 10px;border-radius:6px;background:#efeeff;color:#5b58e8}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 92px)}nav{background:white;border-right:1px solid #e3e8f0;padding:22px 14px}button{font:inherit;cursor:pointer;border:1px solid #e3e8f0;border-radius:7px;background:white;color:inherit;padding:8px 12px}nav button{display:block;width:100%;text-align:left;margin-bottom:8px;border-color:transparent}nav button.active{background:#efeeff;color:#5b58e8}main{padding:26px;min-width:0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:22px}.metric,.card{background:white;border:1px solid #e3e8f0;border-radius:10px;padding:18px}.metric strong{display:block;font-size:30px;color:#5b58e8}.toolbar{display:flex;align-items:center;gap:10px;margin:14px 0}input,select{font:inherit;border:1px solid #dce2ec;border-radius:7px;padding:9px 12px;background:white;color:inherit}input{flex:1;min-width:160px}.table-wrap{overflow:auto;border:1px solid #e3e8f0;border-radius:9px;background:white}table{border-collapse:collapse;width:100%;font-size:12px;min-width:750px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e3e8f0;vertical-align:top}th{background:#f8fafc;color:#66758b}tbody tr{cursor:pointer}tbody tr:hover{background:#f6f5ff}td:first-child{font-family:monospace;white-space:nowrap;color:#5b58e8}a{color:#5b58e8}ul{padding-left:22px}.notice{background:#efeeff;border-radius:8px;padding:14px 18px;margin-bottom:18px;color:#4d4bb5}.detail{position:fixed;inset:0;background:#17213277;display:none;align-items:center;justify-content:center;padding:24px;z-index:5}.detail.open{display:flex}.detail .box{background:white;border-radius:12px;max-width:1000px;width:100%;max-height:90vh;overflow:auto;padding:24px}.detail header{padding:0 0 12px}.detail pre{white-space:pre-wrap;word-break:break-word;font:12px/1.65 ui-monospace,monospace;color:#34445d}.muted{font-size:12px;color:#7b879a}@media(max-width:850px){.layout{grid-template-columns:1fr}nav{display:flex;overflow:auto;gap:8px}nav button{width:auto;white-space:nowrap}.metrics{grid-template-columns:repeat(2,1fr)}main{padding:16px}header{padding:16px}.toolbar{flex-wrap:wrap}}
</style></head><body><header><div><h1>AutoReels <span style="color:#5b58e8">Studio</span> · Source Plan V2.1</h1><p>Kiểm kê giao diện, contracts và lộ trình triển khai · 26/10/2026</p></div><span class="badge">Bộ kế hoạch · chưa có app production</span></header><div class="layout"><nav id="nav"></nav><main><div id="summary"></div><h2 id="title"></h2><p id="description"></p><div class="toolbar" id="toolbar"><input id="search" aria-label="Tìm trong bộ kế hoạch" placeholder="Tìm ID, tên chức năng, node, phase…"><select id="phase" aria-label="Lọc theo phase"><option value="">Tất cả phase</option></select><span id="count" class="muted"></span></div><div id="content"></div></main></div><div class="detail" id="detail" role="dialog" aria-modal="true" aria-label="Chi tiết"><div class="box"><header><h2>Chi tiết registry</h2><button id="close">Đóng</button></header><pre id="json"></pre></div></div><script id="data" type="application/json">__PAYLOAD__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),$=s=>document.querySelector(s);let active='overview',filtered=[];
const tabs=[['overview','Tổng quan'],['actions','124 lệnh UI'],['fields','Fields / đầu vào'],['nodes','40 loại node'],['events','Gestures / phím tắt'],['ux','30 tiện ích Compact'],['steps','125 bước'],['findings','Phát hiện / giới hạn']];
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
tabs.forEach(([id,label])=>{const b=el('button',label);b.dataset.tab=id;b.onclick=()=>{active=id;$('#search').value='';render()};$('#nav').append(b)});
data.plan.phases.forEach(p=>{const o=el('option',p.id+' · '+p.title);o.value=p.id;$('#phase').append(o)});
const definitions={ux:{title:'30 tiện ích thao tác gọn',description:'Phân biệt preview tương tác, bố cục và chức năng production còn trong kế hoạch.',headers:['ID','Chức năng','Preview','Phase','Production'],values:r=>[r.id,r.title,r.previewStatus,r.ownerPhase,r.productionStatus]},actions:{title:'Lệnh và nút giao diện',description:'Mỗi command có owner, service contract, classification và test ID. Observed không có nghĩa chức năng production đã được nghiệm thu.',headers:['ID','Lệnh / nhãn','Phân loại','Phase','Contract'],values:r=>[r.id,r.action+' · '+r.label,r.classification,r.ownerPhase,r.contract]},fields:{title:'Fields và khai báo dữ liệu',description:'Chữ ký field khảo sát; có thể có nhiều instances của cùng nghiệp vụ. Click một dòng để xem options/context.',headers:['ID','DOM / Binding','Type','Phase','Placeholder'],values:r=>[r.id,r.domId||JSON.stringify(r.binding),r.tag+'/'+r.inputType,r.ownerPhase,r.placeholder]},nodes:{title:'Node runtime catalog',description:'Ports/config là thiết kế V2. Có node trong library không chứng minh đã có handler Android.',headers:['ID','Type / tên','Ports V2','Runtime','Config'],values:r=>[r.id,r.type+' · '+r.label,r.productionPorts.join(', ')||'terminal',r.runtime,r.configFields.join(', ')]},events:{title:'Gestures và event families',description:'Những interaction nằm ngoài action dispatcher cũng cần ownership và acceptance.',headers:['ID','Binding','Hành vi','Phase','Test'],values:r=>[r.id,r.binding,r.behavior,r.ownerPhase,r.testId]},steps:{title:'15 phase / 125 bước nghiệm thu',description:'Mỗi bước là một đơn vị triển khai và kiểm chứng, không phải một phiên làm việc. Tất cả implementation đang PLANNED.',headers:['Bước','Công việc','Phase','Nghiệm thu','Test'],values:r=>[r.id,r.title,r.ownerPhase,r.acceptance,r.testId]},findings:{title:'Phát hiện và giới hạn',description:'Phân biệt lỗi tái hiện trong browser, đọc source, giới hạn prototype và nguồn chưa đọc được.',headers:['ID','Phát hiện','Mức độ / phương pháp','Phase','Hướng xử lý'],values:r=>[r.id,r.title,r.severity+' / '+r.method,r.ownerPhase,r.resolution]}};
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===active));$('#summary').replaceChildren();$('#content').replaceChildren();$('#toolbar').hidden=active==='overview';if(active==='overview'){overview();return}const d=definitions[active];$('#title').textContent=d.title;$('#description').textContent=d.description;let rows=active==='steps'?data.plan.phases.flatMap(p=>p.steps.map(s=>({...s,ownerPhase:p.id,phaseTitle:p.title}))):data[active];const q=$('#search').value.trim().toLocaleLowerCase('vi'),phase=$('#phase').value;filtered=rows.filter(r=>(!q||JSON.stringify(r).toLocaleLowerCase('vi').includes(q))&&(!phase||(r.ownerPhase||'P05')===phase));$('#count').textContent=filtered.length+' / '+rows.length;const wrap=el('div');wrap.className='table-wrap';const table=el('table'),head=el('thead'),hr=el('tr');d.headers.forEach(t=>hr.append(el('th',t)));head.append(hr);table.append(head);const body=el('tbody');filtered.forEach(r=>{const tr=el('tr');d.values(r).forEach(v=>tr.append(el('td',v)));tr.onclick=()=>{$('#json').textContent=JSON.stringify(r,null,2);$('#detail').classList.add('open');$('#close').focus()};body.append(tr)});table.append(body);wrap.append(table);$('#content').append(wrap)}
function overview(){$('#title').textContent='Baseline đã hợp nhất';$('#description').textContent='Studio Workspace mới + runtime invariants V1.7. Gói FULL-TRANSFER quá 32 MiB chưa được đọc.';const metrics=el('div');metrics.className='metrics';[['15','Phase'],['125','Bước nghiệm thu'],['124','Lệnh UI'],['40','Node types']].forEach(([n,t])=>{const b=el('div');b.className='metric';b.append(el('span',t),el('strong',n));metrics.append(b)});$('#summary').append(metrics);const notice=el('div','Rà soát 101 trạng thái UI, đối chiếu 42 file reference. Đây là bằng chứng khảo sát và tính nhất quán kế hoạch; chưa có chứng nhận Windows/Android hoặc automation thật.');notice.className='notice';$('#content').append(notice);const c=el('div');c.className='card';c.append(el('h2','Cách xem'));const ul=el('ul');['Chọn danh mục bên trái, tìm kiếm và lọc phase.','Click một dòng để xem toàn bộ contract/acceptance của mục đó.','P00–P07: nền tảng/authoring trên cloud. P08 bắt đầu cần điện thoại khi nghiệm thu.','App tùy chỉnh có thể đăng ký theo package; workflow chạy lịch cần version, validation và test receipt đúng profile.'].forEach(t=>ul.append(el('li',t)));c.append(ul);const a=el('a','Đọc bộ tài liệu chi tiết');a.href='00_START_HERE.md';c.append(a);$('#content').append(c)}
$('#search').oninput=render;$('#phase').onchange=render;$('#close').onclick=()=>$('#detail').classList.remove('open');$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#detail').classList.remove('open')});render();
</script></body></html>'''
(root/'REVIEW_EXPLORER.html').write_text(html.replace('__PAYLOAD__',payload))
print('Review explorer:',root/'REVIEW_EXPLORER.html')
